CREATE VIEW [DBO].[CUSTDEFAULTDELIVERYLOCATIONVIEW] AS SELECT T1.RECID AS CUSTTABLERECID, T1.DATAAREAID AS DATAAREAID, T1.PARTITION AS PARTITION, T1.RECID AS RECID, (CAST ((COALESCE( (SELECT TOP 1 DPL.LOCATION FROM CUSTDEFAULTPARTYLOCATION CDPL INNER JOIN DIRPARTYLOCATION DPL ON CDPL.PARTYLOCATION = DPL.RECID WHERE T1.PARTITION = CDPL.PARTITION AND T1.DATAAREAID = CDPL.DATAAREAID AND T1.RECID = CDPL.CUSTTABLERECID AND CDPL.DEFAULTLOCATIONTYPE = 2), (SELECT TOP 1 CDRL.LOGISTICSLOCATION FROM CUSTDEFAULTROLELOCATION CDRL WHERE T1.PARTITION = CDRL.PARTITION AND T1.DATAAREAID = CDRL.DATAAREAID AND T1.ACCOUNTNUM = CDRL.ACCOUNTNUM AND CDRL.TYPE = 2 ) )) AS BIGINT)) AS LOCATION FROM CUSTTABLE T1